"""Independent ZIP/XML checks of the workbook generated by browser code."""
import sys
import zipfile
import xml.etree.ElementTree as ET

ns = {"s": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}
with zipfile.ZipFile(sys.argv[1]) as book:
    assert book.testzip() is None, "ZIP CRC mismatch"
    for name in book.namelist():
        ET.fromstring(book.read(name))
        assert b"EXCLUDED_SECRET" not in book.read(name)
    sheet = ET.fromstring(book.read("xl/worksheets/sheet1.xml"))
    cells = {c.attrib["r"]: c for c in sheet.findall(".//s:c", ns)}
    text = lambda ref: cells[ref].find("s:is/s:t", ns).text or ""
    assert len(sheet.findall("s:sheetData/s:row", ns)) == 4
    assert text("I1") == "Адрес" and text("J1") == "Статус проверки адреса"
    assert text("H2") == "0000000001"
    assert text("J2") == "Проверено" and text("J3") == "Не найдено" and text("J4") == "Не требуется"
    assert text("B3") == "=1+1" and cells["B3"].attrib["t"] == "inlineStr"
    assert not sheet.findall(".//s:f", ns), "Formula injection"
    assert text("I3") == 'Сынақ & «мекенжай»; <үй>\nЕкінші жол'
    assert cells["K2"].find("s:v", ns).text == "5500"
    assert sheet.find("s:autoFilter", ns).attrib["ref"] == "A1:K4"
    assert sheet.find("s:sheetViews/s:sheetView/s:pane", ns).attrib["state"] == "frozen"
print("XLSX verified: CRC, XML, rows, headers, text phones, statuses, Unicode, line breaks, no formulas or secrets.")
